42	/**
43	 * Replace today's set for one occasion. Delete-then-insert rather than upsert:
44	 * a regenerate may return a different NUMBER of looks, and leftovers from the
45	 * previous set must not survive alongside the new one.
46	 *
47	 * One exception, and it is the reason this function can be called at all after
48	 * a wear: an outfit with a wear log is PINNED. `wear_logs.outfit_id` used to
49	 * have no ON DELETE action, so deleting a worn outfit raised a foreign-key
50	 * violation and the whole regeneration failed. Pinning is also the honest
51	 * product behaviour — what you actually wore today is not a suggestion to be
52	 * thrown away, so it keeps its place in the day's set and the fresh looks are
53	 * numbered past it (`outfits_daily_unique` covers `look_index`).
54	 *
55	 * Returns the new outfit ids, aligned with the `looks` array.
56	 */
57	export async function saveDailyLooks(
58	  userId: string,
59	  occasion: string,
60	  generatedOn: string,
61	  weather: WeatherPayload,
62	  looks: Look[],
63	): Promise<string[]> {
64	  const supabase = await createClient();
65	
66	  const { data: existing } = await supabase
67	    .from("outfits")
68	    .select("id, look_index, wear_logs(worn_on)")
69	    .eq("user_id", userId)
70	    .eq("occasion", occasion)
71	    .eq("generated_on", generatedOn);
72	
73	  // Any wear log pins the row — not just today's. The point is that nothing
74	  // referenced by wear_logs is ever deleted here.
75	  const pinned = (existing ?? []).filter((r) => (r.wear_logs ?? []).length > 0);
76	
77	  let del = supabase
78	    .from("outfits")
79	    .delete()
80	    .eq("user_id", userId)
81	    .eq("occasion", occasion)
82	    .eq("generated_on", generatedOn);
83	  if (pinned.length) del = del.not("id", "in", `(${pinned.map((r) => r.id).join(",")})`);
84	  await del;
85	
86	  const start = freshIndexStart(pinned.map((r) => r.look_index));
87	  const rows = looks.map((look, i) => ({
88	    user_id: userId,
89	    occasion,
90	    generated_on: generatedOn,
91	    look_index: start + i,
92	    look_name: look.name,
93	    ai_reasoning: look.why,
94	    weather_snapshot: weather,
95	    layout: {
96	      anchorIndex: look.anchorIndex,
97	      pieces: look.pieces.map((p) => ({ itemId: p.itemId, slot: p.slot })),
98	    },
99	  }));
100	
101	  const { data: inserted } = await supabase
102	    .from("outfits")
103	    .insert(rows)
104	    .select("id, look_index");
105	  if (!inserted) return [];
106	
107	  // outfit_items is the relational record — it is what wear_logs and future
108	  // analytics join against. The renderable geometry lives in outfits.layout.
109	  const links = inserted.flatMap((row) => {
110	    const look = looks[row.look_index - start];
111	    return (look?.pieces ?? []).map((p) => ({
112	      outfit_id: row.id,
113	      item_id: p.itemId,
114	      slot: p.category,
115	    }));
116	  });
117	  if (links.length) await supabase.from("outfit_items").insert(links);
118	
119	  // Insert order is not guaranteed — place each id at its look's position.
120	  const ids: string[] = [];
121	  for (const row of inserted) ids[row.look_index - start] = row.id;
122	  return ids;
123	}
